                    previous_spy_close <= previous_spy_sma and
                    spy_bar.Close > self.spy_sma.Current.Value
                )
                spy_cross_down = (
                    previous_spy_close >= previous_spy_sma and
                    spy_bar.Close < self.spy_sma.Current.Value
