class IndependentSmaAndRsiStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = [
            self.AddEquity("SPY", Resolution.Daily).Symbol,
            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](4)

        self.aapl_previous_close = None
        self.aapl_rsi_average_gain = None
        self.aapl_rsi_average_loss = None
        self.aapl_rsi_seed_gains = []
        self.aapl_rsi_seed_losses = []
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol) and data.Bars[symbol] is not None:
                close = float(data.Bars[symbol].Close)

                if symbol == self.spy:
                    self.spy_closes.Add(close)

                elif symbol == self.aapl:
                    self.aapl_closes.Add(close)
                    self.UpdateAaplRsi(close)

        if any(not data.Bars.ContainsKey(symbol) or data.Bars[symbol] is None
               for symbol in self.symbols):
            return

        spy_close = float(data.Bars[self.spy].Close)
        aapl_close = float(data.Bars[self.aapl].Close)

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self.IsSpyDownwardCross():
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi is not None and self.aapl_rsi > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self.IsSpyUpwardCross():
            target_value = self.Portfolio.TotalPortfolioValue * 0.40
            shares = int(target_value / spy_close)

            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.IsAaplRedForThreeDays():
            if self.Portfolio.Cash >= 20000:
                shares = int(20000 / aapl_close)

                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares

    def IsSpyUpwardCross(self):
        if not self.spy_closes.IsReady:
            return False

        current_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        previous_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        return self.spy_closes[0] > current_sma and self.spy_closes[1] <= previous_sma

    def IsSpyDownwardCross(self):
        if not self.spy_closes.IsReady:
            return False

        current_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        previous_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        return self.spy_closes[0] < current_sma and self.spy_closes[1] >= previous_sma

    def IsAaplRedForThreeDays(self):
        if not self.aapl_closes.IsReady:
            return False

        return (
            self.aapl_closes[0] < self.aapl_closes[1] and
            self.aapl_closes[1] < self.aapl_closes[2] and
            self.aapl_closes[2] < self.aapl_closes[3]
        )

    def UpdateAaplRsi(self, close):
        if self.aapl_previous_close is None:
            self.aapl_previous_close = close
            return

        change = close - self.aapl_previous_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.aapl_rsi_average_gain is None:
            self.aapl_rsi_seed_gains.append(gain)
            self.aapl_rsi_seed_losses.append(loss)

            if len(self.aapl_rsi_seed_gains) == 14:
                self.aapl_rsi_average_gain = sum(self.aapl_rsi_seed_gains) / 14.0
                self.aapl_rsi_average_loss = sum(self.aapl_rsi_seed_losses) / 14.0
                self.aapl_rsi = self.CalculateRsi(
                    self.aapl_rsi_average_gain,
                    self.aapl_rsi_average_loss
                )
        else:
            self.aapl_rsi_average_gain = (
                self.aapl_rsi_average_gain * 13.0 + gain
            ) / 14.0
            self.aapl_rsi_average_loss = (
                self.aapl_rsi_average_loss * 13.0 + loss
            ) / 14.0
            self.aapl_rsi = self.CalculateRsi(
                self.aapl_rsi_average_gain,
                self.aapl_rsi_average_loss
            )

        self.aapl_previous_close = close

    def CalculateRsi(self, average_gain, average_loss):
        if average_loss == 0:
            return 100.0

        relative_strength = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + relative_strength))
