class ParallelStrategySystem(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_sma = self.sma(self.spy, 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(self.aapl, 14, MovingAverageType.WILDERS, Resolution.DAILY)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

    def on_data(self, data: Slice):
        # Market-state values continue updating whenever their own data is present.
        if data.bars.contains_key(self.aapl):
            aapl_close = data.bars[self.aapl].close
            if self.previous_aapl_close is not None:
                if aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.previous_aapl_close = aapl_close

        # Every subscribed ticker must have today's bar before evaluating rules.
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            if data.bars.contains_key(self.spy):
                self.previous_spy_close = data.bars[self.spy].close
                if self.spy_sma.is_ready:
                    self.previous_spy_sma = self.spy_sma.current.value
            return

        spy_close = data.bars[self.spy].close

        fully_formed = (
            self.spy_sma.is_ready
            and self.aapl_rsi.is_ready
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
            and self.previous_aapl_close is not None
        )

        if fully_formed:
            # Sells before buys.
            if (
                self.strategy_a_lot > 0
                and not self.strategy_a_pending
                and spy_close < self.spy_sma.current.value
                and self.previous_spy_close >= self.previous_spy_sma
            ):
                self.strategy_a_pending = True
                self.market_order(self.spy, -self.strategy_a_lot, tag="StrategyA Sell")

            if (
                self.strategy_b_lot > 0
                and not self.strategy_b_pending
                and self.aapl_rsi.current.value > 60
            ):
                self.strategy_b_pending = True
                self.market_order(self.aapl, -self.strategy_b_lot, tag="StrategyB Sell")

            if (
                self.strategy_a_lot == 0
                and not self.strategy_a_pending
                and spy_close > self.spy_sma.current.value
                and self.previous_spy_close <= self.previous_spy_sma
            ):
                quantity = int((self.portfolio.total_portfolio_value * 0.40) / spy_close)
                if quantity > 0:
                    self.strategy_a_pending = True
                    self.market_order(self.spy, quantity, tag="StrategyA Buy")

            if (
                self.strategy_b_lot == 0
                and not self.strategy_b_pending
                and self.aapl_red_streak >= 3
                and self.portfolio.cash >= 20_000
            ):
                quantity = int(20_000 / data.bars[self.aapl].close)
                if quantity > 0:
                    self.strategy_b_pending = True
                    self.market_order(self.aapl, quantity, tag="StrategyB Buy")

        self.previous_spy_close = spy_close
        if self.spy_sma.is_ready:
            self.previous_spy_sma = self.spy_sma.current.value

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in [OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED]:
            return

        order = self.transactions.get_order_by_id(order_event.order_id)
        if order is None:
            return

        if order.tag.startswith("StrategyA"):
            self.strategy_a_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.strategy_a_pending = False

        elif order.tag.startswith("StrategyB"):
            self.strategy_b_lot += order_event.fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.strategy_b_pending = False
